import React, { useState, useEffect, useCallback } from 'react';

import './App.css';

const API = 'http://localhost:8000';

function App() {
  const [screen, setScreen] = useState('home');
  const [playerName, setPlayerName] = useState('');
  const [category, setCategory] = useState('');
  const [questions, setQuestions] = useState([]);
  const [currentQ, setCurrentQ] = useState(0);
  const [score, setScore] = useState(0);
  const [selected, setSelected] = useState(null);
  const [funFact, setFunFact] = useState('');
  const [timer, setTimer] = useState(30);
  const [streak, setStreak] = useState(0);
  const [bestStreak, setBestStreak] = useState(0);
  const [times, setTimes] = useState([]);
  const [questionStart, setQuestionStart] = useState(null);
  const [leaderboard, setLeaderboard] = useState([]);
  const [playerStats, setPlayerStats] = useState(null);
  const [leaderboardCategory, setLeaderboardCategory] = useState('IPL History');
  const [questionStats, setQuestionStats] = useState([]);

  // Timer logic
  const handleAnswer = useCallback(async (answer) => {
    if (selected !== null) return;

    const timeTaken = 30 - timer;
    setTimes(prev => [...prev, timeTaken]);
    setSelected(answer);

    try {
      const res = await axios.post(`${API}/questions/answer`, null, {
        params: {
          question_id: questions[currentQ].id,
          answer: answer,
          time_taken: timeTaken
        }
      });

      if (res.data.correct) {
        setScore(prev => prev + 1);
        setStreak(prev => {
          const newStreak = prev + 1;
          setBestStreak(best => Math.max(best, newStreak));
          return newStreak;
        });
      } else {
        setStreak(0);
      }
      setFunFact(res.data.fun_fact);
    } catch (err) {
      console.error(err);
    }
  }, [selected, timer, questions, currentQ]);

  useEffect(() => {
    if (screen !== 'quiz' || selected !== null) return;
    if (timer === 0) {
      handleAnswer('X');
      return;
    }
    const interval = setInterval(() => {
      setTimer(prev => prev - 1);
    }, 1000);
    return () => clearInterval(interval);
  }, [screen, timer, selected, handleAnswer]);

  const startQuiz = async (cat) => {
    setCategory(cat);
    try {
      const res = await axios.get(`${API}/questions/`, {
        params: { category: cat }
      });
      setQuestions(res.data);
      setScreen('quiz');
      setCurrentQ(0);
      setScore(0);
      setSelected(null);
      setFunFact('');
      setTimer(30);
      setStreak(0);
      setBestStreak(0);
      setTimes([]);
      setQuestionStart(Date.now());
    } catch (err) {
      console.error(err);
    }
  };

  const nextQuestion = () => {
    if (currentQ + 1 < questions.length) {
      setCurrentQ(prev => prev + 1);
      setSelected(null);
      setFunFact('');
      setTimer(30);
      setQuestionStart(Date.now());
    } else {
      finishQuiz();
    }
  };

  const finishQuiz = async () => {
    const avgTime = times.length > 0
      ? times.reduce((a, b) => a + b, 0) / times.length
      : 0;

    try {
      const res = await axios.post(`${API}/players/submit`, null, {
        params: {
          name: playerName,
          score: score,
          total_questions: questions.length,
          avg_time: avgTime,
          best_streak: bestStreak,
          category: category
        }
      });
      setPlayerStats(res.data.player);
    } catch (err) {
      console.error(err);
    }

    // Load question stats for analytics
    await loadStats(category);
    setScreen('results');
  };

  const loadLeaderboard = async (cat = 'IPL History') => {
    try {
      const res = await axios.get(`${API}/leaderboard/`, {
        params: { category: cat }
      });
      setLeaderboard(res.data);
      setLeaderboardCategory(cat);
    } catch (err) {
      console.error(err);
    }
    setScreen('leaderboard');
  };

  const loadStats = async (cat) => {
    try {
      const res = await axios.get(`${API}/questions/stats`, {
        params: { category: cat }
      });
      setQuestionStats(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const getOptionClass = (opt) => {
    if (selected === null) return 'option-btn';
    const correct = questions[currentQ]?.correct_answer;
    if (opt === correct) return 'option-btn correct';
    if (opt === selected && opt !== correct) return 'option-btn wrong';
    return 'option-btn';
  };

  // HOME SCREEN
  if (screen === 'home') return (
    <div className="app">
      <div className="header">
        <h1>🏏 IPL Quiz</h1>
        <p>Test your IPL knowledge and top the leaderboard!</p>
      </div>
      <div className="home-screen">
        <input
          className="name-input"
          placeholder="Enter your name to start..."
          value={playerName}
          onChange={e => setPlayerName(e.target.value)}
        />
        {playerName.trim() && (
          <>
            <h3>Select a Category</h3>
            <div className="category-buttons">
              <button
                className="category-btn"
                onClick={() => startQuiz('IPL History')}
              >
                🏆 IPL History
              </button>
              <button
                className="category-btn"
                onClick={() => startQuiz('Player Records')}
              >
                🌟 Player Records
              </button>
            </div>
          </>
        )}
        <br />
        <button className="btn btn-secondary" onClick={() => loadLeaderboard('IPL History')}>
  🏆 View Leaderboard
</button>
      </div>
    </div>
  );

  // QUIZ SCREEN
  if (screen === 'quiz') {
    const q = questions[currentQ];
    return (
      <div className="app">
        <div className="header">
          <h1>🏏 IPL Quiz</h1>
        </div>
        <div className="quiz-screen">
          <div className="quiz-header">
            <span className="progress">
              Q {currentQ + 1} of {questions.length}
            </span>
            <span className={`timer ${timer <= 10 ? 'warning' : ''}`}>
              ⏱️ {timer}s
            </span>
            <span className="streak">
              {streak >= 3 ? `🔥 ${streak} Streak!` : `Streak: ${streak}`}
            </span>
          </div>

          <div className="question-card">
            <span className={`difficulty-badge ${q?.difficulty}`}>
              {q?.difficulty?.toUpperCase()}
            </span>
            <p className="question-text">{q?.question}</p>
            <div className="options">
              {['A', 'B', 'C', 'D'].map(opt => (
                <button
                  key={opt}
                  className={getOptionClass(opt)}
                  onClick={() => handleAnswer(opt)}
                  disabled={selected !== null}
                >
                  <strong>{opt})</strong>{' '}
                  {q?.[`option_${opt.toLowerCase()}`]}
                </button>
              ))}
            </div>
          </div>

          {funFact && (
            <div className="fun-fact">
              <span>💡 Fun Fact: </span>{funFact}
            </div>
          )}

          {selected && (
            <div style={{ textAlign: 'center' }}>
              <button className="btn btn-primary" onClick={nextQuestion}>
                {currentQ + 1 < questions.length
                  ? 'Next Question →'
                  : 'See Results 🏆'}
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  // RESULTS SCREEN
  if (screen === 'results') {
    const avgTime = times.length > 0
      ? (times.reduce((a, b) => a + b, 0) / times.length).toFixed(1)
      : 0;

    return (
      <div className="app">
        <div className="header">
          <h1>🏏 IPL Quiz</h1>
        </div>
        <div className="results-screen">
          <h2>Quiz Complete, {playerName}! 🎉</h2>
          <div className="score-circle">
            <h2>{score}/{questions.length}</h2>
            <p>Score</p>
          </div>
          <div className="stats-grid">
            <div className="stat-card">
              <h3>⏱️ {avgTime}s</h3>
              <p>Avg Time Per Question</p>
            </div>
            <div className="stat-card">
              <h3>🔥 {bestStreak}</h3>
              <p>Best Streak</p>
            </div>
            <div className="stat-card">
              <h3>🎯 {playerStats?.accuracy}%</h3>
              <p>Overall Accuracy</p>
            </div>
          </div>
          {playerStats && (
            <div className="question-card" style={{ textAlign: 'left' }}>
              <h3 style={{ color: '#f5a623', marginBottom: '15px' }}>
                📊 Your Stats
              </h3>
              <p>🏆 Best Score Ever: {playerStats.best_score}/{questions.length}</p>
              <p>🎮 Total Quizzes Played: {playerStats.total_quizzes}</p>
              <p>⚡ Best Streak Ever: {playerStats.best_streak}</p>
              <p>⏱️ Avg Time Per Question: {playerStats.avg_time}s</p>
            </div>
          )}
          <div>
            <button
              className="btn btn-primary"
              onClick={() => startQuiz(category)}
            >
              Play Again 🔄
            </button>
            <button
              className="btn btn-secondary"
              onClick={() => setScreen('home')}
            >
              Home 🏠
            </button>
            <button
  className="btn btn-secondary"
  onClick={() => loadLeaderboard('IPL History')}
>
  Leaderboard 🏆
</button>
          </div>
        </div>
      </div>
    );
  }

  // LEADERBOARD SCREEN
  if (screen === 'leaderboard') return (
    <div className="app">
      <div className="header">
        <h1>🏏 IPL Quiz</h1>
      </div>
      <div className="leaderboard-screen">
        <h2 style={{ textAlign: 'center', color: '#f5a623' }}>
          🏆 Global Leaderboard
        </h2>

        {/* Category Tabs */}
        <div className="nav" style={{ marginTop: '20px' }}>
          <button
            className={`nav-btn ${leaderboardCategory === 'IPL History' ? 'active' : ''}`}
            onClick={() => loadLeaderboard('IPL History')}
          >
            🏆 IPL History
          </button>
          <button
            className={`nav-btn ${leaderboardCategory === 'Player Records' ? 'active' : ''}`}
            onClick={() => loadLeaderboard('Player Records')}
          >
            🌟 Player Records
          </button>
        </div>

        <h3 style={{ textAlign: 'center', color: '#aaa', marginBottom: '15px' }}>
          {leaderboardCategory}
        </h3>

        {leaderboard.length === 0 ? (
          <p style={{ textAlign: 'center', color: '#aaa', marginTop: '30px' }}>
            No scores yet for this category — be the first! 🏏
          </p>
        ) : (
          <table className="leaderboard-table">
            <thead>
              <tr>
                <th>Rank</th>
                <th>Player</th>
                <th>Best Score</th>
                <th>Avg Time</th>
                <th>Best Streak</th>
              </tr>
            </thead>
            <tbody>
              {leaderboard.map((player) => (
                <tr key={player.rank}>
                  <td className={`rank-${player.rank}`}>
                    {player.rank === 1 ? '🥇' :
                     player.rank === 2 ? '🥈' :
                     player.rank === 3 ? '🥉' : `#${player.rank}`}
                  </td>
                  <td>{player.name}</td>
                  <td>{player.best_score}/7</td>
                  <td>{player.avg_time}s</td>
                  <td>🔥 {player.best_streak}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        <div style={{ textAlign: 'center', marginTop: '20px' }}>
          <button
            className="btn btn-primary"
            onClick={() => setScreen('home')}
          >
            Play Quiz 🏏
          </button>
        </div>
      </div>
    </div>
  );
}

export default App;
